<?php
require_once __DIR__.'/../../includes/init.php';require_role('admin');require_once __DIR__.'/../../includes/layout.php';$pdo=db();$from=(string)($_GET['from']??date('Y-m-01'));$to=(string)($_GET['to']??date('Y-m-d'));$error='';$rows=[];$total=0;$revenue=0;$summary=[];try{[$a,$b]=valid_date_range($from,$to);$s=$pdo->prepare("SELECT * FROM v_rekap_transaksi WHERE waktu_keluar BETWEEN ? AND ? AND status='keluar' ORDER BY waktu_keluar DESC");$s->execute([$a,$b]);$rows=$s->fetchAll();foreach($rows as $r){$total++;$revenue+=(float)$r['biaya_total'];}$s=$pdo->prepare("SELECT jenis_kendaraan,COUNT(*) AS jumlah,SUM(biaya_total) AS pendapatan FROM v_rekap_transaksi WHERE waktu_keluar BETWEEN ? AND ? AND status='keluar' GROUP BY jenis_kendaraan ORDER BY jenis_kendaraan");$s->execute([$a,$b]);$summary=$s->fetchAll();if(($_GET['format']??'')==='csv') {header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="parkirstrd-laporan-'.$from.'-'.$to.'.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['ID Parkir','Plat Nomor','Jenis','Waktu Masuk','Waktu Keluar','Durasi Jam','Tarif Snapshot','Biaya Total','Area','Petugas']);foreach($rows as $r)fputcsv($out,[$r['id_parkir'],$r['plat_nomor'],$r['jenis_kendaraan'],$r['waktu_masuk'],$r['waktu_keluar'],$r['durasi_jam'],$r['tarif_saat_masuk'],$r['biaya_total'],$r['nama_area'],$r['nama_petugas']]);fclose($out);exit;}}catch(Throwable $e){if($e instanceof InvalidArgumentException){$error=$e->getMessage();}else{error_log('[ParkirSTRD admin report] '.$e->getMessage());$error='Laporan belum dapat diproses. Periksa konfigurasi database.';}}
$labels=array_map(fn($r)=>ucfirst($r['jenis_kendaraan']),$summary);$values=array_map(fn($r)=>(float)$r['pendapatan'],$summary);$chart=['type'=>'doughnut','legend'=>true,'data'=>['labels'=>$labels,'datasets'=>[['label'=>'Pendapatan','data'=>$values,'backgroundColor'=>['#3978ef','#2dc8dc','#26ad80','#f1b84d']]]] ];render_header('Laporan Operasional','laporan');?>
<div class="page-intro"><div><h2>Laporan operasional</h2><p>Rekap transaksi yang telah selesai berdasarkan tanggal keluar.</p></div><?php if(!$error): ?><a class="btn btn-primary" href="<?= h(url('admin/laporan/index.php?from='.rawurlencode($from).'&to='.rawurlencode($to).'&format=csv')) ?>">↓ Ekspor CSV</a><?php endif; ?></div><?php if($error): ?><div class="alert alert-error"><?= h($error) ?></div><?php endif; ?><section class="panel"><form method="get" class="filter-row"><div class="field"><label>Tanggal mulai</label><input type="date" name="from" value="<?= h($from) ?>" required></div><div class="field"><label>Tanggal akhir</label><input type="date" name="to" value="<?= h($to) ?>" required></div><button class="btn btn-primary">Tampilkan laporan</button></form></section><div class="stats-grid"><article class="stat-card"><div class="stat-top"><span class="stat-label">Transaksi selesai</span><span class="stat-icon">⇄</span></div><div class="stat-value"><?= number_format($total) ?></div><div class="stat-foot">Rentang tanggal dipilih</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">Total pendapatan</span><span class="stat-icon green">Rp</span></div><div class="stat-value" style="font-size:21px"><?= h(rupiah($revenue)) ?></div><div class="stat-foot">Berdasarkan biaya yang tersimpan</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">Periode</span><span class="stat-icon cyan">◷</span></div><div class="stat-value" style="font-size:20px"><?= h(date('d M',strtotime($from))) ?> – <?= h(date('d M Y',strtotime($to))) ?></div><div class="stat-foot">Zona waktu Asia/Jakarta</div></article><article class="stat-card"><div class="stat-top"><span class="stat-label">Rata-rata transaksi</span><span class="stat-icon orange">∅</span></div><div class="stat-value" style="font-size:21px"><?= h(rupiah($total?($revenue/$total):0)) ?></div><div class="stat-foot">Pendapatan dibagi jumlah selesai</div></article></div><div class="content-grid"><section class="panel"><div class="panel-heading"><div><h2>Transaksi selesai</h2><p>Detail biaya berdasarkan tarif snapshot.</p></div></div><div class="table-wrap"><table><thead><tr><th>ID</th><th>Plat</th><th>Jenis</th><th>Keluar</th><th>Durasi</th><th>Total</th></tr></thead><tbody><?php foreach(array_slice($rows,0,12) as $r): ?><tr><td class="td-main">#<?= (int)$r['id_parkir'] ?></td><td><?= h($r['plat_nomor']) ?></td><td><?= h(ucfirst($r['jenis_kendaraan'])) ?></td><td><?= h(tanggal($r['waktu_keluar'])) ?></td><td><?= (int)$r['durasi_jam'] ?> jam</td><td class="td-main"><?= h(rupiah($r['biaya_total'])) ?></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="6"><div class="empty-state">Tidak ada transaksi selesai pada periode ini.</div></td></tr><?php endif; ?></tbody></table></div><div class="table-foot"><span>Menampilkan maksimal 12 baris di layar. Ekspor CSV memuat seluruh hasil.</span></div></section><section class="panel"><div class="panel-heading"><div><h2>Pendapatan per jenis</h2><p>Kontribusi tiap jenis kendaraan</p></div></div><div class="chart-wrap" style="height:255px"><canvas data-chart="<?= h(json_encode($chart,JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT)) ?>"></canvas></div><?php if($summary): ?><div class="panel-body"><?php foreach($summary as $r): ?><div class="area-foot" style="padding:8px 0;border-bottom:1px solid #eff2f7"><span><?= h(ucfirst($r['jenis_kendaraan'])) ?> · <?= (int)$r['jumlah'] ?> transaksi</span><strong><?= h(rupiah($r['pendapatan'])) ?></strong></div><?php endforeach; ?></div><?php endif; ?></section></div><?php render_footer(); ?>